require __DIR__.'/header.php'; ?><div class="page-heading"><div><span class="eyebrow">PROPERTY MANAGEMENT</span><h1>Create a property</h1><p>Saved properties appear in the admin inventory and public listing page.</p></div></div><?php if($errors): ?><div class="form-error" role="alert"><ul><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="property-form"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><section class="panel form-section"><h2>Property details</h2><div class="form-grid"><?php foreach(['title'=>['Property title','text',150],'city'=>['City','text',100],'address'=>['Street address (optional)','text',300]] as $key=>$field): ?><label><?= e($field[0]) ?><input name="<?= $key ?>" type="<?= $field[1] ?>" maxlength="<?= $field[2] ?>" value="<?= e($data[$key]) ?>" <?= $key!=='address'?'required':'' ?>></label><?php endforeach; ?><label>Property type<select name="type" required><option value="">Choose type</option><?php foreach($types as $type): ?><option <?= $data['type']===$type?'selected':'' ?>><?= e($type) ?></option><?php endforeach; ?></select></label><label>Purpose<select name="purpose" required><option value="">Choose purpose</option><?php foreach(['Rent','Sell'] as $purpose): ?><option <?= $data['purpose']===$purpose?'selected':'' ?>><?= $purpose ?></option><?php endforeach; ?></select></label><label>Price (USD; monthly for rent)<input type="number" name="price" min="0" max="100000000000" step="0.01" value="<?= e($data['price']) ?>" required></label><?php foreach(['beds'=>'Bedrooms','baths'=>'Bathrooms','area'=>'Area (sq.ft)'] as $key=>$label): ?><label><?= e($label) ?><input type="number" name="<?= $key ?>" min="<?= $key==='area'?'0.01':'0' ?>" max="<?= $key==='area'?'100000000':'100' ?>" step="<?= $key==='area'?'0.01':'1' ?>" value="<?= e($data[$key]) ?>" required></label><?php endforeach; ?></div><label>Description<textarea name="description" rows="5" maxlength="10000" required><?= e($data['description']) ?></textarea></label><label>Amenities (one per line)<textarea name="amenities" rows="3" maxlength="2000" placeholder="Parking&#10;Security&#10;Balcony"><?= e($data['amenities']) ?></textarea></label><label class="checkbox-label"><input type="checkbox" name="featured" value="1" <?= $data['featured']==='1'?'checked':'' ?>> Feature this property</label></section><section class="panel form-section"><h2>Cover photo</h2><p>JPEG, PNG or WebP, up to 5 MB. Re-select your photo if the form reports an error.</p><label>Upload photo<input id="property-photo" type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><img id="photo-preview" alt="Selected property photo preview" hidden></section><div class="form-actions"><a href="./properties">Cancel</a><button class="primary-button" type="submit">Create property</button></div></form><?php require __DIR__.'/footer.php'; ?>
